const raw = $input.first()?.json ?? {};
const source = 'twelve_data';
const core = true;

const empty =
  raw == null ||
  (typeof raw === 'object' && !Array.isArray(raw) && Object.keys(raw).length === 0);

const isCredentialError =
  typeof raw?.error === 'string' && /credentials? not found/i.test(raw.error) ||
  typeof raw?.message === 'string' && /credentials? not found/i.test(raw.message);

const failed = Boolean(
  raw?.error ||
  raw?.errors ||
  raw?.status === 'error' ||
  (raw?.code && raw?.message)
);

const sanitizeError = (r) => {
  if (!r) return 'Source request failed';

  if (typeof r === 'string') {
    return r.replace(/\s+/g, ' ').trim().slice(0, 300);
  }

  const status =
    r.status ??
    r.statusCode ??
    r.response?.status ??
    r.error?.status ??
    r.error?.statusCode ??
    null;

  const candidates = [
    r.message,
    r.error?.message,
    typeof r.error === 'string' ? r.error : null,
    Array.isArray(r.errors) ? r.errors.map(x => x?.message || x).filter(Boolean).join('; ') : r.errors,
  ].filter(Boolean);

  let msg = String(candidates[0] || 'Source request failed')
    .replace(/\s+/g, ' ')
    .trim();

  // Collapse verbose transport/runtime details and strip stack traces / internal paths.
  msg = msg
    .replace(/AxiosError:.*$/i, '')
    .replace(/\bat .*$/i, '')
    .replace(/\/usr\/local\/lib\/node_modules\/n8n[^\s]*/g, '[internal]')
    .trim();

  // Normalize common authentication failures to a concise template-safe message.
  if (/credentials? not found/i.test(msg)) return 'Credentials not found';
  if (/apikey.*incorrect|api key.*incorrect|not specified/i.test(msg)) {
    return status ? `HTTP ${status}: API key missing or invalid` : 'API key missing or invalid';
  }
  if (/401/.test(msg) || status === 401) {
    return 'HTTP 401: authentication failed';
  }
  if (/403/.test(msg) || status === 403) {
    return 'HTTP 403: access forbidden';
  }
  if (/429/.test(msg) || status === 429) {
    return 'HTTP 429: rate limit exceeded';
  }

  if (status && !/^HTTP\s+\d+/i.test(msg)) msg = `HTTP ${status}: ${msg}`;

  return msg.slice(0, 300);
};

const series = {};
if (!failed && !empty) {
  for (const [symbol, p] of Object.entries(raw)) {
    if (!p || !Array.isArray(p.values)) continue;
    const values = p.values.slice(0, 2);
    const current = values[0] || null;
    const previous = values[1] || null;
    const a = Number(current?.close);
    const b = Number(previous?.close);

    series[symbol] = {
      meta: p.meta || null,
      current,
      previous,
      change_percent:
        Number.isFinite(a) && Number.isFinite(b) && b !== 0
          ? ((a - b) / b) * 100
          : null,
    };
  }
}

const invalid = !failed && !empty && Object.keys(series).length === 0;
const status = failed ? 'error' : empty ? 'empty' : invalid ? 'invalid' : 'ok';

return [{
  json: {
    source,
    core,
    status,
    data: status === 'ok' ? { series } : null,
    error:
      status === 'error'
        ? sanitizeError(raw)
        : status === 'invalid'
          ? 'Unexpected source payload shape'
          : null,
  },
}];

