const r = $input.first().json;

// AI Agent normally returns its final answer in `output`.
// Keep a few fallbacks so the validator remains tolerant of small node-version differences.
const candidate =
  r?.output ??
  r?.text ??
  r?.response ??
  r?.message ??
  r?.content ??
  null;

let text = candidate;

if (Array.isArray(text)) {
  text =
    text?.[0]?.content?.[0]?.text ??
    text?.[0]?.text ??
    JSON.stringify(text);
}

if (text && typeof text === 'object') {
  text =
    text?.content?.[0]?.text ??
    text?.text ??
    JSON.stringify(text);
}

if (!text) throw new Error('AI Agent returned no output.');

let b;
try {
  b = typeof text === 'string' ? JSON.parse(text) : text;
} catch (e) {
  throw new Error('AI Agent response was not valid JSON: ' + e.message);
}

if (b.market_regime && typeof b.market_regime === 'object') {
  const label = String(b.market_regime.label || '').toLowerCase();
  b.market_regime = label.includes('risk-off')
    ? 'risk_off'
    : label.includes('risk-on')
      ? 'risk_on'
      : 'neutral';
}

if (!['risk_on','mild_risk_on','neutral','mild_risk_off','risk_off'].includes(b.market_regime)) {
  throw new Error('Unexpected market_regime: ' + b.market_regime);
}

for (const k of [
  'missing_sources',
  'assets',
  'events_today',
  'top_news',
  'drivers',
  'opportunities',
  'watch_next'
]) {
  if (!Array.isArray(b[k])) b[k] = [];
}

const p = $('Prepare Data for AI Model').item.json;
const cfg = $('Setup Workflow Configuration').first().json;

// Canonical asset schema for DB/dashboard consumers.
b.assets = b.assets.map(a => ({
  symbol: a.symbol ?? a.name ?? '',
  price: a.price ?? a.close ?? a.price_usd ?? a.latest_yield_percent ?? null,
  change_percent: a.change_percent ?? a.change_24h_percent ?? null,
  direction: a.direction ?? null,
  signal: a.signal ?? null,
  comment: a.comment ?? '',
}));

b.drivers = b.drivers.map(d => ({
  title: d.title ?? d.driver ?? '',
  explanation: d.explanation ?? d.evidence ?? d.detail ?? '',
  impact: d.impact ?? null,
}));

b.watch_next = b.watch_next
  .map(w => {
    if (typeof w === 'string') return w.trim();
    if (!w || typeof w !== 'object') return '';
    return [
      w.item ?? w.event ?? w.title ?? '',
      w.focus ?? w.status_note ?? w.note ?? '',
      w.scheduled_local_time ?? w.scheduled_time ?? ''
    ].filter(Boolean).join(' — ').trim();
  })
  .filter(Boolean);

b.opportunities = b.opportunities
  .map(o => ({
    name: o.name ?? o.area ?? o.tema ?? o.title ?? '',
    thesis: o.thesis ?? o.view ?? o.obrazlozenje ?? '',
    catalyst: o.catalyst ?? '',
    risk: o.risk ?? o.caveat ?? o.rizik ?? '',
    invalidation: o.invalidation ?? '',
    horizon: o.horizon ?? '',
  }))
  .filter(o => o.name || o.thesis);

return [{
  json: {
    ...b,
    model_provider: cfg.model_provider || 'custom',
    model_name: cfg.model_name || 'user-selected',
    raw_sources: p.normalized_sources,
    source_health: p.source_health,
    core_source_failures: p.core_source_failures,
  },
}];

const b = $input.first().json;
const NL = String.fromCharCode(10);
const MAX = 4000;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const clean = (v, max = 1000) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
};

const regimes = {
  risk_on: ['🟢', 'Risk-on'],
  mild_risk_on: ['🟩', 'Mild risk-on'],
  neutral: ['🟡', 'Neutral'],
  mild_risk_off: ['🟠', 'Mild risk-off'],
  risk_off: ['🔴', 'Risk-off'],
};

const [regimeEmoji, regimeLabel] = regimes[b.market_regime] || ['⚪', b.market_regime || 'Unknown'];

const footer = '<i>Informational analysis only, not individualized financial advice.</i>';
const lines = [];

const currentText = (extra = '') => [...lines, extra, '', footer].join(NL);
const add = (line = '') => {
  if (currentText(line).length <= MAX) {
    lines.push(line);
    return true;
  }
  return false;
};

const addBlock = (blockLines) => {
  const candidate = [...lines, ...blockLines, '', footer].join(NL);
  if (candidate.length <= MAX) {
    lines.push(...blockLines);
    return true;
  }
  return false;
};

let generated = '';
if (b.generated_at) {
  try {
    const dt = DateTime.fromISO(b.generated_at).setZone($('Setup Workflow Configuration').first().json.report_timezone);
    generated = dt.isValid ? dt.toFormat('dd LLL yyyy · HH:mm') : b.generated_at;
  } catch {
    generated = b.generated_at;
  }
}

