add(`${regimeEmoji} <b>${esc(regimeLabel)}</b>${generated ? ` · ${esc(generated)}` : ''}`);
add('');

if (b.headline) {
  add(`<b>${esc(clean(b.headline, 220))}</b>`);
  add('');
}

if (b.summary) {
  // Keep as much of the full summary as comfortably fits.
  add(esc(clean(b.summary, 1050)));
  add('');
}

