if (Array.isArray(b.assets) && b.assets.length) {
  const block = ['<b>📈 Markets</b>'];
  for (const a of b.assets.slice(0, 10)) {
    const change = a.change_percent ?? a.change ?? null;
    const direction = a.direction || (Number(change) > 0 ? 'up' : Number(change) < 0 ? 'down' : 'flat');
    const arrow = direction === 'up' ? '▲' : direction === 'down' ? '▼' : '→';
    const pct = change !== null && Number.isFinite(Number(change))
      ? ` ${arrow} ${Math.abs(Number(change)).toFixed(2)}%`
      : '';
    block.push(`${esc(a.symbol || a.name || 'Unknown')}  ${esc(a.price ?? a.current_price ?? a.value ?? 'n/a')}${pct}`);
  }
  if (addBlock(block)) add('');
}

// Today's macro.
if (Array.isArray(b.events_today) && b.events_today.length) {
  const block = ['<b>📅 Macro Today</b>'];
  for (const e of b.events_today.slice(0, 4)) {
    let when = e.time || '';
    try {
      const dt = DateTime.fromISO(e.time, { setZone: true }).setZone($('Setup Workflow Configuration').first().json.report_timezone);
      if (dt.isValid) when = dt.toFormat('HH:mm');
    } catch {}
    const detail = e.actual != null ? ` · actual ${e.actual}` :
      e.forecast != null ? ` · fcst ${e.forecast}` : '';
    block.push(`• ${esc(when)} ${esc(e.country || '')} ${esc(e.event || '')}${esc(detail)}`.trim());
  }
  if (addBlock(block)) add('');
}

// Drivers: include explanations until near Telegram limit.
if (Array.isArray(b.drivers) && b.drivers.length) {
  add('<b>🔑 Key Drivers</b>');
  for (const d of b.drivers.slice(0, 5)) {
    const title = d.title || 'Market driver';
    const explanation = clean(d.explanation || '', 420);
    if (!add(`• <b>${esc(title)}</b>${explanation ? ` — ${esc(explanation)}` : ''}`)) break;
  }
  add('');
}

// News.
if (Array.isArray(b.top_news) && b.top_news.length) {
  if (add('<b>📰 Top News</b>')) {
    for (const n of b.top_news.slice(0, 3)) {
      const title = clean(n.title || 'Untitled', 220);
      const source = n.source ? ` — ${esc(n.source)}` : '';
      const relevance = clean(n.relevance || '', 280);
      if (!add(`• ${esc(title)}${source}${relevance ? ` · ${esc(relevance)}` : ''}`)) break;
    }
    add('');
  }
}

// Opportunities.
if (Array.isArray(b.opportunities) && b.opportunities.length) {
  if (add('<b>🎯 Setups / Opportunities</b>')) {
    for (const o of b.opportunities.slice(0, 4)) {
      const name = o.name || o.title || '';
      if (!name) continue;
      const thesis = clean(o.thesis || '', 320);
      const catalyst = clean(o.catalyst || '', 180);
      let line = `• <b>${esc(name)}</b>`;
      if (thesis) line += ` — ${esc(thesis)}`;
      if (catalyst) line += ` | Catalyst: ${esc(catalyst)}`;
      if (!add(line)) break;
    }
    add('');
  }
}

// Watch next gets priority near the end.
if (Array.isArray(b.watch_next) && b.watch_next.length) {
  if (add('<b>👀 Watch Next</b>')) {
    for (const w of b.watch_next.slice(0, 6)) {
      const text = typeof w === 'string'
        ? clean(w, 320)
        : clean([w.item || w.event || w.title || '', w.focus || w.note || w.scheduled_local_time || ''].filter(Boolean).join(' — '), 320);
      if (!text || !add(`• ${esc(text)}`)) break;
    }
    add('');
  }
}

// Short data notes only if room remains.
if (Array.isArray(b.missing_sources) && b.missing_sources.length) {
  if (add('<b>⚠️ Data Notes</b>')) {
    for (const w of b.missing_sources.slice(0, 4)) {
      const text = typeof w === 'string' ? clean(w, 220) : clean(JSON.stringify(w), 220);
      if (!add(`• ${esc(text)}`)) break;
    }
    add('');
  }
}

let telegram_text = [...lines, footer].join(NL);

// Final fail-safe while preserving valid HTML: remove complete trailing lines, never slice through tags.
while (telegram_text.length > MAX && lines.length) {
  lines.pop();
  telegram_text = [...lines, footer].join(NL);
}

return [{ json: { ...b, telegram_text } }];

const b = $input.first().json;

const clean = (v, max = 1000) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
};

const regimes = {
  risk_on:       { emoji: '🟢', label: 'Risk-on',       color: 3066993 },
  mild_risk_on:  { emoji: '🟩', label: 'Mild risk-on',  color: 5763719 },
  neutral:       { emoji: '🟡', label: 'Neutral',       color: 16705372 },
  mild_risk_off: { emoji: '🟠', label: 'Mild risk-off', color: 15105570 },
  risk_off:      { emoji: '🔴', label: 'Risk-off',      color: 15548997 },
};
const regime = regimes[b.market_regime] || { emoji: '⚪', label: clean(b.market_regime || 'Unknown', 60), color: 9807270 };

let generated = '';
let timestamp = b.generated_at || new Date().toISOString();
try {
  const dt = DateTime.fromISO(timestamp).setZone($('Setup Workflow Configuration').first().json.report_timezone);
  if (dt.isValid) {
    generated = dt.toFormat('dd LLL yyyy · HH:mm');
    timestamp = dt.toUTC().toISO();
  }
} catch {}

const embed = {
  title: clean(`${regime.emoji} ${b.headline || 'Morning Market Briefing'}`, 256),
  description: clean(b.summary || 'No executive summary available.', 1500),
  color: regime.color,
  timestamp,
  footer: { text: `MarketPulse · ${b.model_name || 'AI model'} · Informational analysis only` },
  fields: []
};

const TOTAL_BUDGET = 5700;
const FIELD_VALUE_MAX = 1000;
const FIELD_NAME_MAX = 256;
const MAX_FIELDS = 25;
const charCount = () => {
  let n = (embed.title || '').length + (embed.description || '').length + (embed.footer?.text || '').length;
  for (const f of embed.fields) n += (f.name || '').length + (f.value || '').length;
  return n;
};
const addField = (name, value, inline = false) => {
  if (!value || embed.fields.length >= MAX_FIELDS) return false;
  const field = { name: clean(name, FIELD_NAME_MAX), value: clean(value, FIELD_VALUE_MAX), inline };
  if (charCount() + field.name.length + field.value.length > TOTAL_BUDGET) return false;
  embed.fields.push(field);
  return true;
};
const fmtNum = (v) => {
  if (v === null || v === undefined || v === '') return 'n/a';
  const n = Number(v);
  return Number.isFinite(n) ? String(v) : clean(v, 80);
};

if (Array.isArray(b.assets) && b.assets.length) {
  const rows = b.assets.slice(0, 10).map(a => {
    const change = a.change_percent ?? a.change ?? null;
    const n = Number(change);
    const direction = a.direction || (Number.isFinite(n) ? (n > 0 ? 'up' : n < 0 ? 'down' : 'flat') : 'flat');
    const arrow = direction === 'up' ? '▲' : direction === 'down' ? '▼' : '→';
    const pct = Number.isFinite(n) ? ` ${arrow} ${Math.abs(n).toFixed(2)}%` : '';
    return `**${clean(a.symbol || a.name || 'Unknown', 40)}**  ${fmtNum(a.price ?? a.current_price ?? a.value)}${pct}`;
  });
  addField('📈 Market Snapshot', rows.join('\n'));
}

if (Array.isArray(b.events_today) && b.events_today.length) {
  const rows = b.events_today.slice(0, 5).map(e => {
    let when = clean(e.time || '', 60);
    try {
      const dt = DateTime.fromISO(e.time, { setZone: true }).setZone($('Setup Workflow Configuration').first().json.report_timezone);
      if (dt.isValid) when = dt.toFormat('HH:mm');
    } catch {}
    const actual = e.actual != null ? ` · actual ${clean(e.actual, 50)}` : '';
    const forecast = e.actual == null && e.forecast != null ? ` · fcst ${clean(e.forecast, 50)}` : '';
    return `• **${when || 'TBD'}** ${clean(e.country || '', 15)} ${clean(e.event || '', 150)}${actual}${forecast}`;
  });
  addField('📅 Macro Today', rows.join('\n'));
}

if (Array.isArray(b.drivers) && b.drivers.length) {
  const rows = b.drivers.slice(0, 5).map(d => {
    const title = clean(d.title || 'Market driver', 100);
    const explanation = clean(d.explanation || '', 260);
    return `• **${title}**${explanation ? ` — ${explanation}` : ''}`;
  });
  addField('🔑 Key Drivers', rows.join('\n'));
}

if (Array.isArray(b.top_news) && b.top_news.length) {
  const rows = b.top_news.slice(0, 3).map(n => {
    const title = clean(n.title || 'Untitled', 180);
    const source = n.source ? ` — *${clean(n.source, 60)}*` : '';
    const relevance = n.relevance ? `\n  ${clean(n.relevance, 220)}` : '';
    return `• **${title}**${source}${relevance}`;
  });
  addField('📰 Top News', rows.join('\n'));
}

if (Array.isArray(b.opportunities) && b.opportunities.length) {
  const rows = b.opportunities.slice(0, 4).map(o => {
    const name = clean(o.name || o.title || 'Setup', 100);
    const thesis = clean(o.thesis || '', 220);
    const catalyst = clean(o.catalyst || '', 120);
    const risk = clean(o.risk || '', 120);
    let s = `• **${name}**`;
    if (thesis) s += ` — ${thesis}`;
    if (catalyst) s += `\n  *Catalyst:* ${catalyst}`;
    if (risk) s += ` · *Risk:* ${risk}`;
    return s;
  });
  addField('🎯 Setups / Opportunities', rows.join('\n'));
}

if (Array.isArray(b.watch_next) && b.watch_next.length) {
  const rows = b.watch_next.slice(0, 6).map(w => {
    const text = typeof w === 'string' ? clean(w, 260) : clean([
      w.item || w.event || w.title || '',
      w.focus || w.note || '',
      w.scheduled_local_time || ''
    ].filter(Boolean).join(' — '), 260);
    return text ? `• ${text}` : '';
  }).filter(Boolean);
  addField('👀 Watch Next', rows.join('\n'));
}

if (Array.isArray(b.missing_sources) && b.missing_sources.length) {
  const rows = b.missing_sources.slice(0, 4).map(x => {
    const text = typeof x === 'string' ? clean(x, 220) : clean(JSON.stringify(x), 220);
    return `• ${text}`;
  });
  addField('⚠️ Data Notes', rows.join('\n'));
}

const meta = [
  generated ? `Generated: ${generated} ${$('Setup Workflow Configuration').first().json.report_timezone}` : null,
  `Regime: ${regime.label}`,
  `Model: ${b.model_name || 'user-selected'}`
].filter(Boolean).join(' · ');
addField('ℹ️ Brief Metadata', meta, false);

return [{ json: { ...b, discord_embed: embed } }];
